import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangleIcon } from './icons';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-screen bg-slate-50 dark:bg-slate-950 text-slate-800 dark:text-slate-200 p-4">
            <div className="bg-white dark:bg-slate-900 border border-red-200 dark:border-red-900 p-8 max-w-md w-full rounded-lg shadow-lg">

                <div className="flex flex-col items-center text-center gap-4 mb-6">
                    <div className="p-3 bg-red-100 dark:bg-red-900/20 rounded-full">
                        <AlertTriangleIcon className="w-8 h-8 text-red-600 dark:text-red-400" />
                    </div>
                    <div>
                        <h1 className="text-xl font-bold text-slate-900 dark:text-white">System Error</h1>
                        <p className="text-sm text-slate-500 mt-1">The application encountered an unexpected state.</p>
                    </div>
                </div>

                <div className="bg-slate-100 dark:bg-black/30 p-3 rounded text-xs font-mono text-red-600 dark:text-red-400 mb-6 overflow-auto max-h-32">
                    {this.state.error?.toString()}
                </div>

                <button 
                    onClick={() => window.location.reload()}
                    className="w-full py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-md transition-colors shadow-sm"
                >
                    Reload Application
                </button>
            </div>
        </div>
      );
    }

    return this.props.children;
  }
}

