                                    <button onClick={() => setShowBodyMap(true)} className="p-2 text-slate-500 hover:text-blue-600 transition-colors rounded-md hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700" title="Open Body Map">
                                        <BodyIcon className="w-5 h-5" />
                                    </button>
                                    <button onClick={() => fileInputRef.current?.click()} className="p-2 text-slate-500 hover:text-blue-600 transition-colors rounded-md hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700" title="Attach File">
                                        <PaperclipIcon className="w-5 h-5" />
                                    </button>
                                    <button onClick={() => cameraInputRef.current?.click()} className="p-2 text-slate-500 hover:text-blue-600 transition-colors rounded-md hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700" title="Camera Capture">
                                        <CameraIcon className="w-5 h-5" />
                                    </button>
                                    {currentMode !== ChatModeEnum.Live && (
                                        <button 
                                            onClick={() => toggleListening(prompt)} 
                                            className={`p-2 transition-colors rounded-md hover:bg-slate-100 dark:hover:bg-slate-700 ${isListening ? 'text-red-600 bg-red-50 dark:bg-red-900/20 animate-pulse border border-red-200 dark:border-red-900' : 'text-slate-500 hover:text-blue-600 dark:text-slate-400'}`}
                                            title="Dictate Text"
                                        >
                                            <MicrophoneIcon className="w-5 h-5" />
                                        </button>
                                    )}
                                </>
                            )}

                             {/* Execute Button */}
                            {(!isLiveSessionActive && currentMode !== ChatModeEnum.Live) && (
                                <button 
                                    onClick={showStopButton ? onStop : handleSendClick}
                                    disabled={!showStopButton && (isInputDisabled || (!prompt.trim() && !uploadedFile))}
                                    className={`ml-2 flex-shrink-0 h-9 w-9 rounded-md flex items-center justify-center transition-all shadow-sm ${
                                        showStopButton
                                        ? 'bg-slate-700 text-white hover:bg-slate-600'
                                        : 'bg-blue-600 hover:bg-blue-700 text-white disabled:opacity-50 disabled:bg-slate-200 dark:disabled:bg-slate-800 dark:disabled:text-slate-500'
                                    }`}
                                >
                                    {showStopButton ? <StopIcon className="w-4 h-4" /> : <SendIcon className="w-4 h-4" />}
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </footer>
    );
};

