import React, { useMemo, useEffect, useState } from 'react';
import { PatientContext, PatientStatus } from '../patient-management/types';
import { UserIcon, AlertTriangleIcon, CheckIcon, ActivityIcon, XCircleIcon, ClockIcon } from '../../components/icons';

interface PatientCardProps {
    patient: PatientContext;
    isActive: boolean;
    onClick: () => void;
    onDelete: (e: React.MouseEvent) => void;
}

// Configuration for the "Live" themes based on status
const THEME_CONFIG: Record<PatientStatus, { 
    bg: string; 
    border: string; 
    text: string; 
    icon: React.FC<any>; 
    pulse: string; 
    glow: string;
}> = {
    'Critical': {
        bg: 'bg-red-50 dark:bg-red-950/30',
        border: 'border-red-300 dark:border-red-800',
        text: 'text-red-800 dark:text-red-300',
        icon: AlertTriangleIcon,
        pulse: 'animate-ping', 
        glow: 'shadow-sm'
    },
    'Stable': {
        bg: 'bg-emerald-50 dark:bg-emerald-950/30',
        border: 'border-emerald-300 dark:border-emerald-800',
        text: 'text-emerald-800 dark:text-emerald-300',
        icon: ActivityIcon,
        pulse: 'animate-pulse', 
        glow: 'shadow-sm'
    },
    'New Admission': {
        bg: 'bg-indigo-50 dark:bg-indigo-950/30',
        border: 'border-indigo-300 dark:border-indigo-800',
        text: 'text-indigo-800 dark:text-indigo-300',
        icon: UserIcon,
        pulse: 'animate-bounce',
        glow: 'shadow-sm'
    },
