        bg: 'bg-blue-50 dark:bg-blue-950/30',
        border: 'border-blue-300 dark:border-blue-800',
        text: 'text-blue-800 dark:text-blue-300',
        icon: CheckIcon,
        pulse: 'hidden', 
        glow: 'shadow-none'
    }
};

const formatTimeAgo = (timestamp: number) => {
    const seconds = Math.floor((Date.now() - timestamp) / 1000);
    if (seconds < 60) return 'Just now';
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}m ago`;
    const hours = Math.floor(minutes / 60);
    return `${hours}h ago`;
};

const PatientCard: React.FC<PatientCardProps> = ({ patient, isActive, onClick, onDelete }) => {
    const theme = THEME_CONFIG[patient.status] || THEME_CONFIG['New Admission'];
    const StatusIcon = theme.icon;
    const [timeAgo, setTimeAgo] = useState(formatTimeAgo(patient.lastActive));

    // Update time ago every minute
    useEffect(() => {
        const interval = setInterval(() => setTimeAgo(formatTimeAgo(patient.lastActive)), 60000);
        return () => clearInterval(interval);
    }, [patient.lastActive]);

    // Extract primary diagnosis for display
    const primaryDiagnosis = useMemo(() => {
        if (patient.entities.diagnosis.length > 0) return patient.entities.diagnosis[0];
        return "Undiagnosed";
    }, [patient.entities.diagnosis]);

    return (
        <div
            onClick={onClick}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => e.key === 'Enter' && onClick()}
            className={`
                w-full text-left rounded-md border transition-all duration-200 group relative overflow-hidden cursor-pointer
                ${isActive 
                    ? `border-l-4 translate-x-1 ${theme.bg} ${theme.border} ${theme.glow}`
                    : 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-800 border-l-4 border-l-transparent hover:border-slate-300 dark:hover:border-slate-700'
                }
                ${isActive ? theme.border.replace('border', 'border-l-') : ''} 
            `}
            style={{ borderLeftColor: isActive ? undefined : 'transparent' }} 
        >
            <div className="p-3 relative z-10">
                {/* Header: Name & Live Status */}
                <div className="flex items-start justify-between mb-2">
                    <div className="flex flex-col min-w-0">
                        <span className={`text-sm font-sans font-bold tracking-tight truncate transition-colors ${isActive ? 'text-slate-900 dark:text-white' : 'text-slate-700 dark:text-slate-300'}`}>
                            {patient.name}
                        </span>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            {/* Live Pulse Indicator */}
                            <span className="relative flex h-2 w-2">
                              <span className={`${theme.pulse} absolute inline-flex h-full w-full rounded-full opacity-75 ${theme.text.replace('text-', 'bg-')}`}></span>
                              <span className={`relative inline-flex rounded-full h-2 w-2 ${theme.text.replace('text-', 'bg-')}`}></span>
                            </span>
                            <span className={`text-[10px] font-mono font-bold uppercase ${isActive ? theme.text : 'text-slate-500 dark:text-slate-400'}`}>
                                {patient.status}
                            </span>
                        </div>
                    </div>

                    {/* Delete Action (Top Right) */}
                    <button 
                        type="button"
                        onClick={(e) => { 
                            e.preventDefault();
                            e.stopPropagation(); 
                            onDelete(e); 
                        }}
                        className={`
                            relative z-20 p-1 rounded-sm transition-all duration-200
                            ${isActive 
                                ? 'text-slate-500 hover:text-red-600 hover:bg-red-100' 
                                : 'text-slate-400 hover:text-red-600 hover:bg-slate-100 dark:hover:bg-slate-800 opacity-0 group-hover:opacity-100'
                            }
                        `}
                        title="Delete Context"
                    >
                        <XCircleIcon className="w-4 h-4" />
                    </button>
                </div>

                {/* Body: Diagnosis & Time */}
                <div className="flex items-center justify-between mt-3">
                    <div className={`
                        px-2 py-0.5 rounded-sm border text-[10px] font-mono font-semibold truncate max-w-[120px]
                        ${isActive 
                            ? `${theme.bg} ${theme.border} ${theme.text} border-opacity-50` 
                            : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400'
                        }
                    `}>
                        {primaryDiagnosis}
                    </div>

                    <div className="flex items-center gap-1 text-[10px] text-slate-500 dark:text-slate-400 font-mono font-medium">
                        <ClockIcon className="w-3 h-3" />
                        <span>{timeAgo}</span>
                    </div>
                </div>

                {/* Footer: Alerts (Conditional) */}
                {(patient.entities.allergies.length > 0 || patient.entities.codeStatus !== 'Full Code') && (
                    <div className="mt-2 pt-2 border-t border-slate-100 dark:border-slate-800 flex gap-1 flex-wrap">
                         {patient.entities.codeStatus !== 'Full Code' && (
                             <span className="text-[9px] font-bold px-1.5 py-0.5 bg-purple-100 dark:bg-purple-900/40 text-purple-800 dark:text-purple-200 rounded-sm uppercase tracking-tight border border-purple-200 dark:border-purple-800">
                                {patient.entities.codeStatus}
                             </span>
                         )}
                         {patient.entities.allergies.length > 0 && (
                             <span className="text-[9px] font-bold px-1.5 py-0.5 bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-200 rounded-sm uppercase tracking-tight border border-red-200 dark:border-red-800">
                                {patient.entities.allergies.length} Allergies
                             </span>
                         )}
                    </div>
                )}
            </div>
        </div>
    );
};

