    onViewImage?: (src: string, alt: string) => void;
}

const Message: React.FC<MessageProps> = ({ message, isLoading, isLast, onImageLoad, onViewImage }) => {
    const isModel = message.role === 'model';
    const [isCopied, setIsCopied] = useState(false);

    // Safety Alert Detection
    const isCriticalAlert = isModel && message.content.includes("🛑 CRITICAL SAFETY WARNING");

    // Determine content to pass to renderer
    const contentToRender = (message.role === 'user' && message.displayContent) 
        ? message.displayContent 
        : message.content;

    const handleCopy = () => {
        navigator.clipboard.writeText(message.content);
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000);
    };

    return (
        <div className={`flex flex-col gap-2 group animate-slide-up ${isModel ? 'items-start' : 'items-end'}`}>

            {/* Technical Header Label / Timestamp */}
            <div className={`flex items-center gap-2 px-1 select-none transition-opacity duration-300 ${isModel ? 'opacity-90' : 'opacity-60'}`}>
                {isModel && <div className={`h-1.5 w-1.5 rounded-full ${isCriticalAlert ? 'bg-red-600 animate-pulse' : 'bg-blue-600'}`}></div>}
                <span className={`text-[10px] font-mono uppercase tracking-widest ${isModel ? (isCriticalAlert ? 'text-red-600 font-bold' : 'text-blue-700 dark:text-blue-400 font-semibold') : 'text-slate-600 dark:text-slate-400'}`}>
                    {isModel ? (isCriticalAlert ? 'CRITICAL_SAFETY_INTERVENTION' : 'CIL_OUTPUT') : 'USER_INPUT'}
                </span>
                {isModel && (
                     <span className="text-[9px] font-mono text-slate-400 border-l border-slate-300 dark:border-slate-600 pl-2">
                        {new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                    </span>
                )}
            </div>

            {/* Main Data Block */}
            <div className={`
                relative max-w-full md:max-w-3xl p-5 rounded-lg transition-all duration-200 overflow-hidden shadow-sm
                ${isModel 
                    ? isCriticalAlert 
                        ? 'bg-red-50 dark:bg-red-950/30 border-l-4 border-red-600 text-slate-900 dark:text-slate-100 border border-red-100 dark:border-red-900'
                        : 'bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 border-l-4 border-l-blue-600 text-left' 
                    : 'bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-slate-200 text-left rounded-tr-none'
                }
            `}>

                {/* Critical Alert Badge Overlay */}
                {isCriticalAlert && (
                    <div className="absolute top-0 right-0 bg-red-600 text-white px-3 py-1 text-[9px] font-bold uppercase tracking-widest rounded-bl-lg shadow-sm flex items-center gap-2 z-10">
                        <AlertTriangleIcon className="w-3 h-3" />
                        <span>Protocol Violation</span>
                    </div>
                )}

                {/* Copy Button */}
                {isModel && !isLoading && (
                    <button 
                        onClick={handleCopy}
                        className="absolute top-3 right-3 p-1.5 rounded-md text-slate-400 hover:text-blue-600 hover:bg-slate-100 dark:hover:bg-slate-800 opacity-0 group-hover:opacity-100 transition-all z-20"
                        title="Copy to Clipboard"
                    >
                        {isCopied ? <CheckIcon className="w-3.5 h-3.5 text-green-600" /> : <ClipboardIcon className="w-3.5 h-3.5" />}
                    </button>
                )}

                {/* File Attachment Visualization */}
                {message.filePreview && (
                    <div className="mb-4 pb-4 border-b border-slate-100 dark:border-slate-800">
                         {message.filePreview.type.startsWith('image/') && message.filePreview.url ? (
                             <div className="relative inline-block group/img">
                                <button 
                                    onClick={() => onViewImage?.(message.filePreview!.url!, message.filePreview!.name)}
                                    className="block overflow-hidden border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-black/20 rounded-md"
                                >
                                    <img 
                                        src={message.filePreview.url} 
                                        alt={message.filePreview.name} 
                                        onLoad={onImageLoad}
                                        className="max-w-[150px] md:max-w-[200px] max-h-[150px] md:max-h-[200px] object-contain block group-hover/img:scale-105 transition-transform duration-500" 
                                    />
                                </button>
                                <div className="mt-2 flex items-center justify-between text-[10px] font-mono text-slate-500 dark:text-slate-400 max-w-[200px]">
                                    <span className="truncate">IMG: {message.filePreview.name}</span>
                                    <span className="text-blue-600 opacity-0 group-hover/img:opacity-100 transition-opacity cursor-pointer font-bold tracking-wider">[EXPAND]</span>
                                </div>
                            </div>
                        ) : (
                             <div className="flex items-center gap-3 p-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md w-fit pr-6">
                                <div className="p-2 bg-white dark:bg-slate-700 rounded-sm shadow-sm border border-slate-200 dark:border-slate-600">
                                    <DocumentTextIcon className="w-5 h-5 text-slate-600 dark:text-slate-300" />
                                </div>
                                <div>
                                    <p className="font-mono text-xs font-bold text-slate-900 dark:text-white">{message.filePreview.name}</p>
                                    <p className="text-[10px] text-slate-500 uppercase tracking-wide mt-0.5">DATA_INGESTED</p>
                                 </div>
                            </div>
                        )}
                    </div>
                )}

                {/* Content Rendering Delegated to MessageContent */}
                <MessageContent 
                    content={contentToRender} 
                    role={message.role} 
                    isLoading={!!isLoading} 
                    isLast={!!isLast} 
                />

                {/* Grounding Sources Footer */}
                {message.sources && message.sources.length > 0 && (
                    <div className="mt-6 pt-4 border-t border-slate-100 dark:border-slate-800">
                        <div className="flex items-center gap-2 mb-3">
                            <ShieldCheckIcon className="w-3 h-3 text-slate-400" />
                            <span className="text-[10px] font-mono font-bold text-slate-500 uppercase tracking-widest">Verified Sources</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {message.sources.map((source, i) => {
                                if (source.web) {
                                    const isTrusted = isHighCredibilitySource(source.web.uri);
                                    return (
                                        <a key={i} href={source.web.uri} target="_blank" rel="noopener noreferrer"
                                            className={`flex items-center gap-1.5 px-3 py-1.5 text-[10px] font-medium border transition-all rounded-full max-w-full
                                                ${isTrusted 
                                                    ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-200 dark:border-emerald-800 text-emerald-700 dark:text-emerald-400 hover:bg-emerald-100' 
                                                    : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 hover:bg-slate-100'
                                                }`}
                                        >
                                            {isTrusted ? <ShieldCheckIcon className="w-3 h-3 text-emerald-600" /> : <LinkIcon className="w-3 h-3 text-blue-500" />}
                                            <span className="truncate max-w-[200px]">{source.web.title}</span>
                                        </a>
                                    );
                                }
                                if (source.maps) {
                                    return (
                                        <a key={i} href={source.maps.uri} target="_blank" rel="noopener noreferrer"
                                            className="flex items-center gap-1.5 bg-blue-50 dark:bg-blue-900/20 hover:bg-blue-100 border border-blue-200 dark:border-blue-800 px-3 py-1.5 text-[10px] font-medium text-blue-700 dark:text-blue-300 transition-all rounded-full"
                                        >
                                            <MapPinIcon className="w-3 h-3 text-blue-600" />
                                            <span className="truncate max-w-[200px]">{source.maps.title}</span>
                                        </a>
                                    );
                                }
                                return null;
                            })}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Message;

import React, { useMemo } from 'react';
import { parse } from 'marked';
import DOMPurify from 'dompurify';
import BriefingReport from './BriefingReport';
import ImageAnalysisReport from './ImageAnalysisReport';
import LabReport from './LabReport';
import InteractionMatrix from './InteractionMatrix';
import ReasoningIndicator from './ReasoningIndicator';
import { isJsonBriefing, isImageAnalysis, isLabReport, isInteractionMatrix } from '../utils';
import { ChatMode } from '../types';

interface MessageContentProps {
    content: string;
    role: 'user' | 'model';
    isLoading: boolean;
    isLast: boolean;
}

const MessageContent: React.FC<MessageContentProps> = ({ content, role, isLoading, isLast }) => {
    // 1. Detect Specialized Report Types
    const isBriefing = role === 'model' && isJsonBriefing(content);
    const isAnalysis = role === 'model' && isImageAnalysis(content);
    const isLab = role === 'model' && isLabReport(content);
    const isInteraction = role === 'model' && isInteractionMatrix(content);

    // 2. Detect Streaming JSON State (prevent showing raw brackets while generating)
    const isStreamingJson = useMemo(() => {
        if (role !== 'model' || !isLoading || !isLast) return false;
        const trimmed = content.trim();
        const hasJsonStart = trimmed.includes('```json') || trimmed.startsWith('{');
        // If it looks like JSON but isn't a complete recognized report yet
        return hasJsonStart && !(isBriefing || isAnalysis || isLab || isInteraction);
    }, [content, role, isLoading, isLast, isBriefing, isAnalysis, isLab, isInteraction]);

    // 3. Detect Placeholder Loading State
    const isPlaceholderLoading = role === 'model' && isLast && isLoading && !content.trim();

    // 4. Memoized Markdown Parsing (Performance)
    const parsedHtml = useMemo(() => {
        if (isStreamingJson || isPlaceholderLoading || isBriefing || isAnalysis || isLab || isInteraction) return null;
        // Basic markdown parsing
        const html = parse(content, { breaks: true, gfm: true }) as string;
        return DOMPurify.sanitize(html);
    }, [content, isStreamingJson, isPlaceholderLoading, isBriefing, isAnalysis, isLab, isInteraction]);

    // --- RENDERERS ---

    if (isBriefing) return <BriefingReport content={content} />;
    if (isAnalysis) return <ImageAnalysisReport content={content} />;
    if (isLab) return <LabReport content={content} />;
    if (isInteraction) return <InteractionMatrix content={content} />;

    if (isPlaceholderLoading) {
        return <ReasoningIndicator mode={ChatMode.Standard} />;
    }

    if (isStreamingJson) {
        return (
            <div className="flex flex-col gap-2 p-4 w-full min-w-[300px] animate-pulse bg-slate-50 dark:bg-slate-900/50 border-l-2 border-blue-400">
                <div className="flex items-center gap-2 text-blue-600">
                    <div className="w-4 h-4 border-2 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-mono text-xs uppercase tracking-widest font-bold">Synthesizing Clinical Data Structure...</span>
                </div>
                <div className="space-y-2 opacity-50 mt-2">
                    <div className="h-2 bg-slate-300 dark:bg-slate-700 w-3/4 rounded-sm"></div>
                    <div className="h-2 bg-slate-300 dark:bg-slate-700 w-1/2 rounded-sm"></div>
                    <div className="h-2 bg-slate-300 dark:bg-slate-700 w-full rounded-sm"></div>
                </div>
            </div>
        );
    }

    const typographyClasses = `
        prose prose-sm dark:prose-invert max-w-none text-slate-800 dark:text-slate-200 leading-relaxed font-sans
        prose-headings:font-sans prose-headings:font-bold prose-headings:tracking-tight prose-headings:text-slate-900 dark:prose-headings:text-white
        prose-p:my-2 prose-ul:my-2 prose-li:my-0.5
        prose-strong:font-bold prose-strong:text-slate-900 dark:prose-strong:text-white
        prose-blockquote:bg-red-50 dark:prose-blockquote:bg-red-900/20 
        prose-blockquote:border-l-4 prose-blockquote:border-red-600 
        prose-blockquote:text-red-900 dark:prose-blockquote:text-red-100 
        prose-blockquote:py-3 prose-blockquote:px-4 prose-blockquote:rounded-r-md
        prose-blockquote:not-italic prose-blockquote:font-semibold
        prose-code:font-mono prose-code:text-[11px] prose-code:bg-slate-100 dark:prose-code:bg-slate-800 prose-code:px-1.5 prose-code:py-0.5 prose-code:rounded-sm prose-code:text-slate-900 dark:prose-code:text-slate-200 prose-code:font-medium
        ${isLoading && isLast ? 'animate-soft-stream' : ''}
    `;

    return (
        <div 
            className={typographyClasses} 
            dangerouslySetInnerHTML={{ __html: parsedHtml || '' }}
        ></div>
    );
};

export default MessageContent;

import React, { useMemo, useEffect, useState } from 'react';
import { PatientContext, PatientStatus } from '../patient-management/types';
import { UserIcon, AlertTriangleIcon, CheckIcon, ActivityIcon, XCircleIcon, ClockIcon } from '../../components/icons';

interface PatientCardProps {
    patient: PatientContext;
    isActive: boolean;
    onClick: () => void;
    onDelete: (e: React.MouseEvent) => void;
}

// Simplified Clinical Theme Config (No animations/glows)
const STATUS_STYLES: Record<PatientStatus, { 
    border: string; 
    badgeBg: string; 
    badgeText: string;
    icon: React.FC<any>; 
}> = {
    'Critical': {
        border: 'border-l-red-600',
        badgeBg: 'bg-red-100 dark:bg-red-900/50',
        badgeText: 'text-red-700 dark:text-red-200',
        icon: AlertTriangleIcon
    },
    'Stable': {
        border: 'border-l-emerald-500',
        badgeBg: 'bg-emerald-100 dark:bg-emerald-900/50',
        badgeText: 'text-emerald-700 dark:text-emerald-200',
        icon: ActivityIcon
    },
    'New Admission': {
        border: 'border-l-blue-500',
        badgeBg: 'bg-blue-100 dark:bg-blue-900/50',
        badgeText: 'text-blue-700 dark:text-blue-200',
        icon: UserIcon
    },
    'Discharge Ready': {
        border: 'border-l-slate-500',
        badgeBg: 'bg-slate-100 dark:bg-slate-800',
        badgeText: 'text-slate-700 dark:text-slate-300',
        icon: CheckIcon
    }
};

const formatTimeAgo = (timestamp: number) => {
    const seconds = Math.floor((Date.now() - timestamp) / 1000);
    if (seconds < 60) return 'Just now';
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}m`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours}h`;
    return `${Math.floor(hours / 24)}d`;
};

const PatientCard: React.FC<PatientCardProps> = ({ patient, isActive, onClick, onDelete }) => {
    const styles = STATUS_STYLES[patient.status] || STATUS_STYLES['New Admission'];
    const StatusIcon = styles.icon;
    const [timeAgo, setTimeAgo] = useState(formatTimeAgo(patient.lastActive));

    useEffect(() => {
        const interval = setInterval(() => setTimeAgo(formatTimeAgo(patient.lastActive)), 60000);
        return () => clearInterval(interval);
    }, [patient.lastActive]);

    const primaryDiagnosis = useMemo(() => {
        if (patient.entities.diagnosis.length > 0) return patient.entities.diagnosis[0];
        return "Undiagnosed";
    }, [patient.entities.diagnosis]);

    return (
        <div
            onClick={onClick}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => e.key === 'Enter' && onClick()}
            className={`
                w-full text-left rounded-sm border mb-2 transition-colors duration-150 group relative
                ${isActive 
                    ? `bg-white dark:bg-slate-800 border-slate-300 dark:border-slate-600 shadow-sm border-l-4 ${styles.border}`
                    : 'bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-800 border-l-4 border-l-transparent hover:border-slate-300 dark:hover:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800/50'
                }
            `}
        >
            <div className="p-3">
                {/* Header: Name & Time */}
                <div className="flex items-start justify-between mb-2">
                    <span className={`text-sm font-bold truncate pr-2 ${isActive ? 'text-slate-900 dark:text-white' : 'text-slate-700 dark:text-slate-300'}`}>
                        {patient.name}
                    </span>
                    <div className="flex items-center gap-1 flex-shrink-0">
                        <span className="text-[10px] font-mono text-slate-400">{timeAgo}</span>
                        <button 
                            type="button"
                            onClick={(e) => { 
                                e.preventDefault();
                                e.stopPropagation(); 
                                onDelete(e); 
                            }}
                            className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity p-0.5"
                            title="Delete Context"
                        >
                            <XCircleIcon className="w-3.5 h-3.5" />
                        </button>
                    </div>
                </div>

                {/* Status Badge */}
                <div className="flex items-center justify-between">
                    <div className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-sm text-[10px] font-bold uppercase tracking-wide ${styles.badgeBg} ${styles.badgeText}`}>
                        <StatusIcon className="w-3 h-3" />
                        <span>{patient.status}</span>
                    </div>
                </div>

                {/* Diagnosis / Footer */}
                <div className="mt-2 pt-2 border-t border-slate-100 dark:border-slate-800 flex justify-between items-center">
                    <span className="text-[10px] text-slate-500 truncate max-w-[120px]" title={primaryDiagnosis}>
                        {primaryDiagnosis}
                    </span>

                    {/* Compact Alert Indicators */}
                    <div className="flex gap-1">
                        {patient.entities.codeStatus !== 'Full Code' && (
                            <span className="w-2 h-2 rounded-full bg-purple-500" title={`Code Status: ${patient.entities.codeStatus}`}></span>
                        )}
                        {patient.entities.allergies.length > 0 && (
                            <span className="w-2 h-2 rounded-full bg-red-500" title="Allergies Present"></span>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default PatientCard;

import React, { useState, useRef, useEffect } from 'react';
import { usePatientStore } from '../patient-management/usePatientStore';
import { PatientContext, PatientStatus } from '../patient-management/types';
import { AlertTriangleIcon, ActivityIcon, ShieldCheckIcon, CheckIcon, UserIcon } from '../../components/icons';

interface HeadsUpDisplayProps {
    patient: PatientContext;
}

const STATUS_OPTIONS: { value: PatientStatus; color: string; label: string }[] = [
    { value: 'Stable', color: 'bg-emerald-500', label: 'Stable' },
    { value: 'Critical', color: 'bg-red-500', label: 'Critical' },
    { value: 'New Admission', color: 'bg-blue-500', label: 'New Admission' },
    { value: 'Discharge Ready', color: 'bg-slate-500', label: 'Discharge Ready' },
];

const HeadsUpDisplay: React.FC<HeadsUpDisplayProps> = ({ patient }) => {
    const { dispatch } = usePatientStore();
    const { entities, name, status, id } = patient;
    const hasAllergies = entities.allergies.length > 0;
    const codeStatus = entities.codeStatus;

    // Interactions
    const [isEditingName, setIsEditingName] = useState(false);
    const [nameInput, setNameInput] = useState(name);
    const [isStatusMenuOpen, setIsStatusMenuOpen] = useState(false);
    const nameInputRef = useRef<HTMLInputElement>(null);
    const statusMenuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (statusMenuRef.current && !statusMenuRef.current.contains(event.target as Node)) {
                setIsStatusMenuOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleNameSave = () => {
        if (nameInput.trim() !== name) {
            dispatch({ type: 'UPDATE_PATIENT_DETAILS', payload: { id, updates: { name: nameInput.trim() } } });
        }
        setIsEditingName(false);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') handleNameSave();
        if (e.key === 'Escape') {
            setNameInput(name);
            setIsEditingName(false);
        }
    };

    return (
        <div className="sticky top-0 z-20 bg-white dark:bg-slate-950 border-b border-slate-200 dark:border-slate-800 shadow-sm">
            <div className="max-w-6xl mx-auto px-4 py-3 flex flex-col md:flex-row md:items-center justify-between gap-3">

                {/* Left: Patient Identity & Status */}
                <div className="flex items-center gap-4">
                    <div className="p-2 bg-slate-100 dark:bg-slate-900 rounded-full border border-slate-200 dark:border-slate-700">
                        <UserIcon className="w-5 h-5 text-slate-500" />
                    </div>

                    <div>
                        {/* Name Editor */}
                        {isEditingName ? (
                            <input
                                ref={nameInputRef}
                                type="text"
                                value={nameInput}
                                onChange={(e) => setNameInput(e.target.value)}
                                onBlur={handleNameSave}
                                onKeyDown={handleKeyDown}
                                autoFocus
                                className="text-lg font-bold text-slate-900 dark:text-white bg-transparent border-b border-blue-500 focus:outline-none w-full"
                            />
                        ) : (
                            <div 
                                onClick={() => { setIsEditingName(true); setTimeout(() => nameInputRef.current?.focus(), 0); }}
                                className="text-lg font-bold text-slate-900 dark:text-white cursor-pointer hover:underline decoration-slate-300 underline-offset-4 decoration-dotted"
                                title="Click to rename context"
                            >
                                {name}
                            </div>
                        )}

                        {/* Status Switcher */}
                        <div className="relative mt-1" ref={statusMenuRef}>
                            <button 
                                onClick={() => setIsStatusMenuOpen(!isStatusMenuOpen)}
                                className="flex items-center gap-1.5 text-xs font-mono uppercase tracking-wide text-slate-500 hover:text-slate-800 dark:hover:text-slate-300 transition-colors"
                            >
                                <span className={`w-2 h-2 rounded-full ${STATUS_OPTIONS.find(s => s.value === status)?.color || 'bg-slate-400'}`}></span>
                                <span className="font-bold">{status}</span>
                                <span className="text-[10px] ml-1">▼</span>
                            </button>

                            {isStatusMenuOpen && (
                                <div className="absolute top-full left-0 mt-1 w-48 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 shadow-lg rounded-sm py-1 z-50">
                                    {STATUS_OPTIONS.map((opt) => (
                                        <button
                                            key={opt.value}
                                            onClick={() => {
                                                dispatch({ type: 'UPDATE_PATIENT_DETAILS', payload: { id, updates: { status: opt.value } } });
                                                setIsStatusMenuOpen(false);
                                            }}
                                            className="w-full text-left px-3 py-2 text-xs font-bold uppercase hover:bg-slate-50 dark:hover:bg-slate-800 flex items-center gap-2 text-slate-700 dark:text-slate-300"
                                        >
                                            <span className={`w-2 h-2 rounded-full ${opt.color}`}></span>
                                            {opt.label}
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Right: Clinical Safety Summary */}
                <div className="flex flex-wrap gap-2 items-center">
                    {/* Diagnosis Chips */}
                    {entities.diagnosis.length > 0 && (
                        <div className="flex items-center gap-1 mr-2 border-r border-slate-200 dark:border-slate-700 pr-3">
                            {entities.diagnosis.slice(0, 2).map((dx, i) => (
                                <span key={i} className="px-2 py-1 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 text-xs font-medium rounded-sm border border-slate-200 dark:border-slate-700">
                                    {dx}
                                </span>
                            ))}
                        </div>
                    )}

                    {/* Safety Badges - High Contrast */}
                    {hasAllergies ? (
                        <div className="flex items-center gap-2 px-3 py-1.5 bg-red-600 text-white rounded-sm shadow-sm">
                            <AlertTriangleIcon className="w-4 h-4" />
                            <span className="text-xs font-bold uppercase tracking-wide">{entities.allergies.length} Allergies</span>
                        </div>
                    ) : (
