export type ModalType = 'ADD_PATIENT' | 'NONE';

export type ToastType = 'success' | 'error' | 'info';

export interface Toast {
    id: string;
    message: string;
    type: ToastType;
}

export interface UIState {
    isSidebarOpen: boolean;
    activeModal: ModalType;
    toasts: Toast[];
}

export type UIAction =
    | { type: 'TOGGLE_SIDEBAR' }
    | { type: 'SET_SIDEBAR'; payload: boolean }
    | { type: 'OPEN_MODAL'; payload: ModalType }
    | { type: 'CLOSE_MODAL' }
    | { type: 'ADD_TOAST'; payload: Toast }
    | { type: 'REMOVE_TOAST'; payload: string };

import React, { createContext, useContext, useReducer, useCallback } from 'react';
import { UIState, UIAction, ModalType, ToastType } from './types';

const initialState: UIState = {
    isSidebarOpen: true,
    activeModal: 'NONE',
    toasts: []
};

const uiReducer = (state: UIState, action: UIAction): UIState => {
    switch (action.type) {
        case 'TOGGLE_SIDEBAR':
            return { ...state, isSidebarOpen: !state.isSidebarOpen };
        case 'SET_SIDEBAR':
            return { ...state, isSidebarOpen: action.payload };
        case 'OPEN_MODAL':
            return { ...state, activeModal: action.payload };
        case 'CLOSE_MODAL':
            return { ...state, activeModal: 'NONE' };
        case 'ADD_TOAST':
            return { ...state, toasts: [...state.toasts, action.payload] };
        case 'REMOVE_TOAST':
            return { ...state, toasts: state.toasts.filter(t => t.id !== action.payload) };
        default:
            return state;
    }
};

interface UIContextType {
    state: UIState;
    dispatch: React.Dispatch<UIAction>;
    actions: {
        toggleSidebar: () => void;
        setSidebar: (isOpen: boolean) => void;
        openModal: (modal: ModalType) => void;
        closeModal: () => void;
        showToast: (message: string, type?: ToastType) => void;
        removeToast: (id: string) => void;
    };
}

const UIContext = createContext<UIContextType | undefined>(undefined);

export const UIProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [state, dispatch] = useReducer(uiReducer, initialState);

    const toggleSidebar = useCallback(() => dispatch({ type: 'TOGGLE_SIDEBAR' }), []);
    const setSidebar = useCallback((isOpen: boolean) => dispatch({ type: 'SET_SIDEBAR', payload: isOpen }), []);
    const openModal = useCallback((modal: ModalType) => dispatch({ type: 'OPEN_MODAL', payload: modal }), []);
    const closeModal = useCallback(() => dispatch({ type: 'CLOSE_MODAL' }), []);
    const removeToast = useCallback((id: string) => dispatch({ type: 'REMOVE_TOAST', payload: id }), []);

    const showToast = useCallback((message: string, type: ToastType = 'info') => {
        const id = Math.random().toString(36).substring(2, 9);
        dispatch({ type: 'ADD_TOAST', payload: { id, message, type } });
        setTimeout(() => {
            dispatch({ type: 'REMOVE_TOAST', payload: id });
        }, 4000);
    }, []);

    return (
        <UIContext.Provider value={{ 
            state, 
            dispatch, 
            actions: { toggleSidebar, setSidebar, openModal, closeModal, showToast, removeToast } 
        }}>
            {children}
        </UIContext.Provider>
    );
};

export const useUIStore = () => {
    const context = useContext(UIContext);
    if (!context) throw new Error("useUIStore must be used within UIProvider");
    return context;
};

