import React, { useState, useCallback, useEffect } from 'react';
import { ChatMode as ChatModeEnum } from '../../types';
import Header from '../../components/Header';
import MessageList from '../../components/MessageList';
import InputBar from '../../components/InputBar';
import ImageViewer from '../../components/ImageViewer';
import SidebarRoster from '../patient-roster/SidebarRoster';
import HeadsUpDisplay from '../hud/HeadsUpDisplay';
import ScribeInterface from '../scribe/ScribeInterface';
import CDSSContainer from '../cdss/CDSSContainer';
import AddPatientDialog from '../patient-roster/AddPatientDialog';
import { useLiveSession } from '../../hooks/useLiveSession';
import { useFileDragAndDrop } from '../../hooks/useFileDragAndDrop';
import { useChatOrchestrator } from '../../hooks/useChatOrchestrator';
import { DocumentTextIcon } from '../../components/icons';
import { usePatientStore } from '../patient-management/usePatientStore';
import { useUIStore } from '../ui/UIContext';
import { useToast } from '../../components/Toast';

const MainLayout: React.FC = () => {
    // --- Stores ---
    const { state: patientState, dispatch: patientDispatch, activePatient, activeMessages } = usePatientStore();
    const { state: uiState, actions: uiActions } = useUIStore();
    const { showToast } = useToast();

    const { globalChatMode, isLoading } = patientState;
    const { uploadedFile, setUploadedFile, isDragging, clearFile, dragHandlers } = useFileDragAndDrop();

    // --- Local UI State ---
    const [userLocation, setUserLocation] = useState<{latitude: number, longitude: number} | undefined>(undefined);
    const [viewingImage, setViewingImage] = useState<{src: string, alt: string} | null>(null);

    // Responsive Sidebar Check
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 768) uiActions.setSidebar(false);
            else uiActions.setSidebar(true);
        };
        handleResize(); // Init
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, [uiActions]);

    // --- Geolocation ---
    useEffect(() => {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => setUserLocation({ latitude: position.coords.latitude, longitude: position.coords.longitude }),
                (err) => console.debug("Location access denied or failed:", err.message)
            );
        }
    }, []);

    // --- Live Session Integration ---
    const handleLiveTurnComplete = useCallback((userInput: string, modelOutput: string) => {
        if (userInput) patientDispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'user', content: userInput } } });
        if (modelOutput) patientDispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'model', content: modelOutput } } });
    }, [patientDispatch]);

    const { isLive, transcript, startSession, stopSession, error: liveError } = useLiveSession(handleLiveTurnComplete);

    useEffect(() => {
        if (liveError) patientDispatch({ type: 'REQUEST_FAILED', payload: liveError });
    }, [liveError, patientDispatch]);

    useEffect(() => {
        if (globalChatMode !== ChatModeEnum.Live && isLive) stopSession();
    }, [globalChatMode, isLive, stopSession]);

    useEffect(() => {
        if (isLive && globalChatMode !== ChatModeEnum.Live) patientDispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Live });
    }, [isLive, globalChatMode, patientDispatch]);

    // --- Chat Orchestrator ---
    const { handleSend, handleStop, handleClearChat, handleExportChat } = useChatOrchestrator({
        messages: activeMessages, // Pass the ACTIVE patient's messages
        activePatientId: activePatient?.id,
        chatMode: globalChatMode,
        dispatch: patientDispatch,
        uploadedFile,
        setUploadedFile,
        isLive,
        stopSession,
        userLocation,
        clearFile
    });

    const handleViewImage = useCallback((src: string, alt: string) => {
        setViewingImage({ src, alt });
    }, []);

    const toggleLiveSession = useCallback(() => isLive ? stopSession() : startSession(activeMessages), [isLive, stopSession, startSession, activeMessages]);

    // --- Handlers for Global UI ---
    const handleCreatePatient = (name: string) => {
        patientDispatch({ type: 'CREATE_PATIENT', payload: { name } });
        uiActions.closeModal();
        showToast(`Patient context '${name}' initialized`, 'success');
    };

    if (!process.env.API_KEY) {
         return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-50 dark:bg-slate-900 text-slate-800 dark:text-slate-200 p-4">
                <div className="bg-white dark:bg-slate-800 p-8 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm max-w-md text-center">
                    <div className="text-red-500 text-5xl mb-4">⚠️</div>
                    <h1 className="text-xl font-bold mb-2">API Key Missing</h1>
                    <p className="text-slate-600 dark:text-slate-400">Environment variable <code>API_KEY</code> is required.</p>
                </div>
            </div>
         );
    }

    return (
        <div 
            className="flex h-[100dvh] font-sans overflow-hidden relative text-slate-900 dark:text-slate-100 bg-white dark:bg-slate-950"
            {...dragHandlers}
        >
            {/* Global Modals */}
            <AddPatientDialog 
                isOpen={uiState.activeModal === 'ADD_PATIENT'} 
                onClose={uiActions.closeModal} 
                onSubmit={handleCreatePatient} 
            />

            {/* Overlay for Drag & Drop */}
            {isDragging && (
                <div className="absolute inset-0 z-50 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center m-4 rounded-lg animate-fade-in border-2 border-dashed border-blue-500">
                    <div className="flex flex-col items-center text-white">
                        <DocumentTextIcon className="w-16 h-16 mb-4" />
                        <h2 className="text-2xl font-bold">Drop File to Ingest</h2>
                    </div>
                </div>
            )}

            {/* Image Modal */}
            {viewingImage && (
                <ImageViewer 
                    src={viewingImage.src} 
                    alt={viewingImage.alt} 
                    onClose={() => setViewingImage(null)} 
                />
            )}

            {/* --- LAYOUT STRUCTURE --- */}

            {/* 1. Sidebar (Left) */}
            <SidebarRoster />

            {/* 2. Main Content (Right) */}
            <div className="flex-1 flex flex-col min-w-0 relative z-10 bg-slate-50 dark:bg-slate-900">
                <Header
                    currentMode={globalChatMode}
                    onModeChange={(mode) => patientDispatch({ type: 'SET_CHAT_MODE', payload: mode })}
                    onClearChat={handleClearChat}
                    onExportChat={handleExportChat}
                    onToggleSidebar={uiActions.toggleSidebar}
                />

                {/* 3. Heads Up Display (HUD) */}
                {activePatient && (
                    <HeadsUpDisplay patient={activePatient} />
                )}

                {/* 4. CDSS Overlay */}
                <CDSSContainer />

                {/* CONDITIONAL RENDER: SCRIBE vs CHAT */}
                {globalChatMode === ChatModeEnum.Scribe ? (
                    <ScribeInterface />
                ) : (
                    <>
                        <MessageList 
                            messages={activeMessages} 
                            isLoading={isLoading} 
                            isLive={isLive} 
                            liveTranscript={transcript} 
                            onViewImage={handleViewImage}
                        />

                        <InputBar
                            onSend={handleSend}
                            onClearFile={clearFile}
                            setUploadedFile={setUploadedFile}
                            uploadedFile={uploadedFile}
                            isLoading={isLoading}
                            currentMode={globalChatMode}
                            toggleLiveSession={toggleLiveSession}
                            isLiveSessionActive={isLive}
                            onStop={handleStop}
                        />
                    </>
                )}
            </div>
        </div>
    );
};

export default MainLayout;

import React, { useRef } from 'react';
import { usePatientStore } from '../patient-management/usePatientStore';
import PatientCard from './PatientCard';
import { ChevronLeftIcon, UsersIcon, DownloadIcon, ClipboardIcon, PlusIcon } from '../../components/icons';
import { useToast } from '../../components/Toast';
import { PatientContext } from '../patient-management/types';
import { useUIStore } from '../ui/UIContext';

const SidebarRoster: React.FC = () => {
    const { state, dispatch } = usePatientStore();
    const { state: uiState, actions: uiActions } = useUIStore();
    const { showToast } = useToast();
    const fileInputRef = useRef<HTMLInputElement>(null);

    const isOpen = uiState.isSidebarOpen;
    const patientsList = (Object.values(state.patients) as PatientContext[]).sort((a, b) => b.lastActive - a.lastActive);

    const handleSwitch = (id: string) => {
        dispatch({ type: 'SWITCH_PATIENT', payload: { id } });
    };

    const handleDelete = (id: string, name: string) => {
        if (Object.keys(state.patients).length <= 1) {
            showToast("Cannot delete the only active patient context.", 'error');
            return;
        }

        if (confirm(`Are you sure you want to delete the context for "${name}"?\nThis action cannot be undone.`)) {
             dispatch({ type: 'DELETE_PATIENT', payload: { id } });
             showToast(`Patient context deleted`, 'info');
        }
    };

    const handleExportData = () => {
        try {
            const dataStr = JSON.stringify(state);
            const blob = new Blob([dataStr], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `medibrief-backup-${new Date().toISOString().split('T')[0]}.json`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showToast('System backup downloaded successfully', 'success');
        } catch (e) {
            showToast('Failed to export system data', 'error');
        }
    };

    const handleImportClick = () => {
        fileInputRef.current?.click();
    };

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const importedState = JSON.parse(event.target?.result as string);
                if (importedState && importedState.patients) {
                    dispatch({ type: 'HYDRATE', payload: importedState });
                    showToast('System data restored successfully', 'success');
                } else {
                    throw new Error("Invalid format");
                }
            } catch (error) {
                showToast('Invalid backup file format', 'error');
            }
        };
        reader.readAsText(file);
        e.target.value = ''; // Reset input
    };

    return (
        <>
            <aside 
                className={`
                    flex-shrink-0 bg-slate-50/80 dark:bg-[#080b14]/80 backdrop-blur-xl border-r border-slate-200 dark:border-white/5 transition-all duration-300 ease-in-out relative z-40
                    ${isOpen ? 'w-72' : 'w-0 opacity-0 md:opacity-100 md:w-12'}
                `}
            >
                <button
                    onClick={uiActions.toggleSidebar}
                    className={`
                        absolute -right-3 top-20 z-50 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full p-1 shadow-md text-slate-500 hover:text-blue-500 transition-colors
                        ${isOpen ? 'rotate-0' : 'rotate-180'}
                    `}
                    aria-label="Toggle Roster"
                >
                    <ChevronLeftIcon className="w-3 h-3" />
                </button>

                <div className={`flex flex-col h-full overflow-hidden ${!isOpen && 'hidden md:flex'}`}>

                    {/* Header */}
                    <div className="p-4 border-b border-slate-200 dark:border-white/5 flex items-center justify-between h-16">
                        {isOpen ? (
                            <div className="flex items-center gap-2 text-slate-700 dark:text-slate-200">
                                <UsersIcon className="w-4 h-4" />
                                <span className="font-mono text-xs font-bold uppercase tracking-widest">Active Roster</span>
                            </div>
                        ) : (
                            <div className="w-full flex justify-center">
                                <UsersIcon className="w-5 h-5 text-slate-400" />
                            </div>
                        )}

                        {isOpen && (
                            <div className="text-[10px] font-mono text-slate-400 bg-slate-200 dark:bg-white/5 px-1.5 py-0.5 rounded-sm">
                                {patientsList.length}
                            </div>
                        )}
                    </div>

                    {/* Patient List */}
                    <div className="flex-1 overflow-y-auto p-2 space-y-2">
                        {isOpen ? (
                            patientsList.map(patient => (
                                <PatientCard
                                    key={patient.id}
                                    patient={patient}
                                    isActive={patient.id === state.activePatientId}
                                    onClick={() => handleSwitch(patient.id)}
                                    onDelete={(e) => handleDelete(patient.id, patient.name)}
                                />
                            ))
                        ) : (
                            <div className="flex flex-col gap-2 items-center mt-2">
                                {patientsList.map(patient => (
                                    <button
                                        key={patient.id}
                                        onClick={() => handleSwitch(patient.id)}
                                        className={`w-8 h-8 rounded-sm flex items-center justify-center border transition-all relative group
                                            ${patient.id === state.activePatientId 
                                                ? 'bg-blue-600 border-blue-600 text-white' 
                                                : 'bg-white dark:bg-white/5 border-slate-200 dark:border-white/10 text-slate-400 hover:border-blue-400'
                                            }
                                        `}
                                        title={patient.name}
                                    >
                                        <span className="text-[10px] font-bold font-mono">
                                            {patient.name.substring(0, 2).toUpperCase()}
                                        </span>
                                        <div className={`absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full border-2 border-white dark:border-slate-900 ${
                                            patient.status === 'Critical' ? 'bg-red-500' : 
                                            patient.status === 'Stable' ? 'bg-emerald-500' : 'bg-slate-400'
                                        }`}></div>
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Footer Actions */}
                    <div className="p-3 border-t border-slate-200 dark:border-white/5 bg-slate-100/50 dark:bg-black/20 space-y-2">
                        {isOpen ? (
                            <>
                                <button 
                                    onClick={() => uiActions.openModal('ADD_PATIENT')}
                                    className="w-full flex items-center justify-center gap-2 bg-white dark:bg-white/5 border border-slate-300 dark:border-white/10 hover:border-blue-500 text-slate-600 dark:text-slate-300 px-3 py-2 rounded-sm text-xs font-bold uppercase tracking-wide transition-all shadow-sm"
                                >
                                    <PlusIcon className="w-3.5 h-3.5" />
                                    <span>Add Patient</span>
                                </button>
                                <div className="flex gap-2">
                                    <button 
                                        onClick={handleExportData}
                                        className="flex-1 flex items-center justify-center gap-1.5 bg-slate-200 dark:bg-white/5 border border-transparent hover:bg-slate-300 dark:hover:bg-white/10 text-slate-600 dark:text-slate-400 px-2 py-1.5 rounded-sm text-[10px] font-mono font-bold uppercase transition-colors"
                                        title="Backup Data"
                                    >
                                        <DownloadIcon className="w-3 h-3" />
                                        <span>Backup</span>
                                    </button>
                                    <button 
                                        onClick={handleImportClick}
                                        className="flex-1 flex items-center justify-center gap-1.5 bg-slate-200 dark:bg-white/5 border border-transparent hover:bg-slate-300 dark:hover:bg-white/10 text-slate-600 dark:text-slate-400 px-2 py-1.5 rounded-sm text-[10px] font-mono font-bold uppercase transition-colors"
                                        title="Restore Data"
                                    >
                                        <ClipboardIcon className="w-3 h-3" />
                                        <span>Restore</span>
                                    </button>
                                </div>
                            </>
                        ) : (
                             <button 
                                onClick={() => uiActions.openModal('ADD_PATIENT')}
                                className="w-full flex items-center justify-center p-2 text-slate-500 hover:text-blue-500"
                                title="Add Patient"
                            >
                                <PlusIcon className="w-5 h-5" />
                            </button>
                        )}
                        <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleFileImport} />
                    </div>
                </div>
            </aside>

            {/* Mobile Overlay */}
            {isOpen && (
                <div 
                    className="md:hidden fixed inset-0 z-30 bg-slate-900/50 backdrop-blur-sm"
                    onClick={uiActions.toggleSidebar}
                ></div>
            )}
        </>
    );
};

export default SidebarRoster;

import React, { useReducer, useEffect, useContext, createContext } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { PatientContext, PatientEntityData } from './types';
import { FHIRObservation } from '../fhir/types';
import { ChatMessage, ChatMode, GroundingSource } from '../../types';

// --- State Definitions ---

export interface PatientStoreState {
    patients: Record<string, PatientContext>;
    activePatientId: string;
    globalChatMode: ChatMode;
    isLoading: boolean;
    error: string | null;
}

// --- Actions ---

export type PatientAction =
    | { type: 'CREATE_PATIENT'; payload: { name?: string } }
    | { type: 'DELETE_PATIENT'; payload: { id: string } }
    | { type: 'SWITCH_PATIENT'; payload: { id: string } }
    | { type: 'UPDATE_PATIENT_DETAILS'; payload: { id: string; updates: Partial<PatientContext> } }
    | { type: 'UPDATE_PATIENT_ENTITIES'; payload: { id: string; entities: Partial<PatientEntityData> } }
    | { type: 'INGEST_CLINICAL_DATA'; payload: { id: string; observations: FHIRObservation[] } }
    // Chat Actions (Target Active Patient)
    | { type: 'START_REQUEST'; payload: { userMessage: ChatMessage } }
    | { type: 'ADD_RESPONSE_PLACEHOLDER' }
    | { type: 'APPEND_TO_LAST_MESSAGE'; payload: { chunk: string; sources?: GroundingSource[] } }
    | { type: 'REQUEST_FINISH' }
    | { type: 'ADD_FULL_RESPONSE'; payload: { message: ChatMessage } }
    | { type: 'UPDATE_LAST_MESSAGE_CONTENT'; payload: string }
    | { type: 'REQUEST_FAILED'; payload: string }
    | { type: 'ADD_INTERIM_MESSAGE'; payload: ChatMessage }
    // Global Actions
    | { type: 'SET_CHAT_MODE'; payload: ChatMode }
    | { type: 'SET_LOADING'; payload: boolean }
    | { type: 'RESET_ACTIVE_CHAT' }
    | { type: 'HYDRATE'; payload: PatientStoreState }
    | { type: 'CLEAR_SESSION' };

// --- Initial State Helper ---

const DEFAULT_PATIENT_ID = 'general-context';
// SECURITY UPDATE: Use sessionStorage (Session scope only) instead of localStorage (Persistent).
// This prevents PHI from remaining on shared devices after the tab is closed.
const STORAGE_KEY = 'mediBriefSessionStore_v5'; 

const createDefaultPatient = (): PatientContext => ({
    id: DEFAULT_PATIENT_ID,
    name: 'General Context',
    status: 'New Admission',
    documents: [],
    chatHistory: [],
    entities: { allergies: [], codeStatus: 'Full Code', diagnosis: [] },
    clinicalData: { observations: [] },
    createdAt: Date.now(),
    lastActive: Date.now()
});

const getInitialState = (): PatientStoreState => {
    try {
        const savedState = sessionStorage.getItem(STORAGE_KEY);
        if (savedState) {
            const parsed = JSON.parse(savedState);
            if (parsed.patients && parsed.activePatientId) {
                // Restore active context if valid
                if (parsed.patients[parsed.activePatientId]) {
                    return parsed;
                }
            }
        }
    } catch (e) {
        console.warn("Failed to load patient session, initializing new context.");
    }

    // Fallback: Clean Slate
    const defaultPatient = createDefaultPatient();
    return {
        patients: { [DEFAULT_PATIENT_ID]: defaultPatient },
        activePatientId: DEFAULT_PATIENT_ID,
        globalChatMode: ChatMode.Standard,
        isLoading: false,
        error: null
    };
};

// --- Reducer ---

const patientReducer = (state: PatientStoreState, action: PatientAction): PatientStoreState => {
    const activeId = state.activePatientId;
    const activePatient = state.patients[activeId];

    switch (action.type) {
        case 'HYDRATE':
            return action.payload;
        case 'CLEAR_SESSION':
            sessionStorage.removeItem(STORAGE_KEY);
            const resetPatient = createDefaultPatient();
            return {
                patients: { [DEFAULT_PATIENT_ID]: resetPatient },
                activePatientId: DEFAULT_PATIENT_ID,
                globalChatMode: ChatMode.Standard,
                isLoading: false,
                error: null
            };
        case 'CREATE_PATIENT': {
            const newId = uuidv4();
            const newPatient: PatientContext = {
                ...createDefaultPatient(),
                id: newId,
                name: action.payload.name || `Patient ${Object.keys(state.patients).length + 1}`,
                status: 'New Admission',
            };
            return {
                ...state,
                patients: { ...state.patients, [newId]: newPatient },
                activePatientId: newId
            };
        }
        case 'DELETE_PATIENT': {
            const targetId = action.payload.id;
            // Prevent deleting the last patient or default context if it's the only one
            if (Object.keys(state.patients).length <= 1) return state;

            const newPatients = { ...state.patients };
            delete newPatients[targetId];

            // If we deleted the active patient, switch to another one
            let newActiveId = state.activePatientId;
            if (state.activePatientId === targetId) {
                newActiveId = Object.keys(newPatients)[0];
            }

            return {
                ...state,
                patients: newPatients,
                activePatientId: newActiveId
            };
        }
        case 'SWITCH_PATIENT':
            return {
                ...state,
                activePatientId: action.payload.id
            };
        case 'UPDATE_PATIENT_DETAILS': {
            const targetId = action.payload.id;
            if (!state.patients[targetId]) return state;
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: { ...state.patients[targetId], ...action.payload.updates }
                }
            };
        }
        case 'UPDATE_PATIENT_ENTITIES': {
            const targetId = action.payload.id;
            const targetPatient = state.patients[targetId];
            if (!targetPatient) return state;

            const newEntities = { ...targetPatient.entities };
            const incoming = action.payload.entities;

            if (incoming.allergies && incoming.allergies.length > 0) {
                newEntities.allergies = [...new Set([...newEntities.allergies, ...incoming.allergies])];
            }
            if (incoming.codeStatus) newEntities.codeStatus = incoming.codeStatus;
            if (incoming.diagnosis && incoming.diagnosis.length > 0) {
                 newEntities.diagnosis = [...new Set([...newEntities.diagnosis, ...incoming.diagnosis])];
            }

            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: { ...targetPatient, entities: newEntities }
                }
            };
        }
        case 'INGEST_CLINICAL_DATA': {
            const targetId = action.payload.id;
            const targetPatient = state.patients[targetId];
            if (!targetPatient) return state;

            const existingObs = targetPatient.clinicalData?.observations || [];
            const newObs = action.payload.observations.filter(obs => 
                !existingObs.some(ex => 
                    ex.code.text === obs.code.text && 
                    ex.valueQuantity?.value === obs.valueQuantity?.value &&
                    ex.effectiveDateTime === obs.effectiveDateTime
                )
            );

            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: {
                        ...targetPatient,
                        clinicalData: {
                            ...targetPatient.clinicalData,
                            observations: [...existingObs, ...newObs]
                        }
                    }
                }
            };
        }

        // Chat Actions
        case 'START_REQUEST':
            return {
                ...state,
                isLoading: true,
                error: null,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload.userMessage],
                        lastActive: Date.now()
                    }
                }
            };
        case 'ADD_RESPONSE_PLACEHOLDER':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, { role: 'model', content: '' }]
                    }
                }
            };
        case 'APPEND_TO_LAST_MESSAGE': {
            const history = [...activePatient.chatHistory];
            const lastMsg = history[history.length - 1];
            if (lastMsg && lastMsg.role === 'model') {
                lastMsg.content += action.payload.chunk;
                if (action.payload.sources) {
                    const existing = lastMsg.sources || [];
                    const newSources = action.payload.sources.filter(ns => 
                        !existing.some(es => 
                            (es.web?.uri && es.web.uri === ns.web?.uri) || 
                            (es.maps?.uri && es.maps.uri === ns.maps?.uri)
                        )
                    );
                    lastMsg.sources = [...existing, ...newSources];
                }
            }
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
            };
        }
        case 'REQUEST_FINISH':
            return { ...state, isLoading: false };
        case 'ADD_FULL_RESPONSE':
            return {
                ...state,
                isLoading: false,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload.message],
                        lastActive: Date.now()
                    }
                }
            };
        case 'ADD_INTERIM_MESSAGE':
             return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload]
                    }
                }
            };
        case 'UPDATE_LAST_MESSAGE_CONTENT': {
            const history = [...activePatient.chatHistory];
            const lastMsg = history[history.length - 1];
            if (lastMsg) lastMsg.content = action.payload;
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
            };
        }
        case 'REQUEST_FAILED': {
             const history = [...activePatient.chatHistory];
             const lastMsg = history[history.length - 1];
             if (lastMsg && lastMsg.role === 'model' && !lastMsg.content) {
                 lastMsg.content = `Sorry, I encountered an error.\n\n**Details:** ${action.payload}`;
             } else {
                 history.push({ role: 'model', content: `Sorry, I encountered an error.\n\n**Details:** ${action.payload}` });
             }
             return {
                ...state,
                isLoading: false,
                error: action.payload,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
             };
        }
        case 'RESET_ACTIVE_CHAT':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: [] }
                }
            };

        case 'SET_CHAT_MODE':
            return { ...state, globalChatMode: action.payload };
        case 'SET_LOADING':
            return { ...state, isLoading: action.payload };

        default:
            return state;
    }
};

// --- Context ---

interface PatientContextType {
    state: PatientStoreState;
    dispatch: React.Dispatch<PatientAction>;
    activePatient: PatientContext;
    activeMessages: ChatMessage[];
}

const PatientStoreContext = createContext<PatientContextType | undefined>(undefined);

export const PatientProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [state, dispatch] = useReducer(patientReducer, getInitialState());

    // Persistence Effect (Session Storage)
    useEffect(() => {
        try {
            const stateToSave = {
                ...state,
                // Serialize patients dictionary
                patients: Object.entries(state.patients).reduce((acc, [id, patient]) => {
                    const p = patient as PatientContext;
                    acc[id] = {
                        ...p,
                        // Optimize storage: Don't persist large base64 strings in history
                        chatHistory: p.chatHistory.map(msg => {
                            if (msg.filePreview?.base64) {
                                return { 
                                    ...msg, 
                                    filePreview: { ...msg.filePreview, base64: undefined } 
                                };
                            }
                            return msg;
                        })
                    };
                    return acc;
                }, {} as Record<string, PatientContext>)
            };
            sessionStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
        } catch (e) {
            console.error("Failed to save patient session", e);
        }
    }, [state]);

    const activePatient = state.patients[state.activePatientId];

    return React.createElement(PatientStoreContext.Provider, {
        value: { 
            state, 
            dispatch, 
            activePatient, 
            activeMessages: activePatient?.chatHistory || [] 
        }
    }, children);
};

export const usePatientStore = () => {
    const context = useContext(PatientStoreContext);
    if (!context) {
        throw new Error("usePatientStore must be used within a PatientProvider");
    }
    return context;
};

import React, { useState } from 'react';
import type { ChatMessage, GroundingSource } from '../types';
import { LinkIcon, DocumentTextIcon, ClipboardIcon, CheckIcon, AlertTriangleIcon, ShieldCheckIcon } from './icons';
import MessageContent from './MessageContent';
import { isInteractionMatrix } from '../utils';

// Helper to detect high-credibility domains for medical info
const isHighCredibilitySource = (uri: string) => {
    try {
        const url = new URL(uri);
        const domain = url.hostname.toLowerCase();
        return domain.endsWith('.gov') || 
               domain.endsWith('.org') || 
               domain.endsWith('.edu') || 
               domain.includes('mayoclinic') ||
               domain.includes('webmd') || 
               domain.includes('medscape') ||
               domain.includes('ncbi') ||
               domain.includes('pubmed');
    } catch {
        return false;
    }
};

